import{_t as e,it as t,n,rt as r}from"./chunks/framework.DaD4z1Q-.js";var i=JSON.parse(`{"title":"Update your own code to use prefixed names","description":"Use update_call_sites to rewrite your plugin's own PHP files to use prefixed namespaces, preview the changes with diff and avoid common pitfalls.","frontmatter":{"title":"Update your own code to use prefixed names","description":"Use update_call_sites to rewrite your plugin's own PHP files to use prefixed namespaces, preview the changes with diff and avoid common pitfalls."},"headers":[],"relativePath":"guide/updating-your-code.md","filePath":"guide/updating-your-code.md"}`),a={name:`guide/updating-your-code.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="updating-your-own-code" tabindex="-1">Updating your own code <a class="header-anchor" href="#updating-your-own-code" aria-label="Permalink to “Updating your own code”">​</a></h1><p>Your project&#39;s own files refer to the packages too. A line like <code>use Acme\\Core\\Client;</code> has to become <code>use Acme\\Vendor\\Acme\\Core\\Client;</code> once the package is prefixed. Set <code>update_call_sites</code> and <code>prefix</code> rewrites those files in place:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	&quot;update_call_sites&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="which-files-are-changed" tabindex="-1">Which files are changed <a class="header-anchor" href="#which-files-are-changed" aria-label="Permalink to “Which files are changed”">​</a></h2><ul><li><code>true</code> updates the <code>.php</code> files under the <code>autoload</code> paths in your <code>composer.json</code> (<code>psr-4</code>, <code>psr-0</code>, <code>classmap</code> and <code>files</code>). <code>autoload-dev</code> is not included.</li><li>A list, such as <code>[&quot;src&quot;, &quot;includes/loader.php&quot;]</code>, updates just those files and folders, relative to the project.</li><li><code>false</code>, the default, changes none of your files.</li><li>Your own namespaces are left alone. The vendor and target directories are never touched.</li><li><code>exclude_files_from_update</code> skips files by package, namespace or file pattern.</li></ul><p>You can override the setting for one run with <code>--updateCallSites</code>, <code>--updateCallSites=false</code> or <code>--updateCallSites=src,includes</code>, on <code>prefix</code> and <code>diff</code>.</p><h2 id="precautions" tabindex="-1">Precautions <a class="header-anchor" href="#precautions" aria-label="Permalink to “Precautions”">​</a></h2><p>This changes your source files. Make sure you commit or backup before you run it, and look at the result first:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/strauss-rs.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --updateCallSites</span></span></code></pre></div><p><code>prefix --dry-run</code> also reports how many files would change, without writing them.</p><h2 id="it-does-not-undo-itself" tabindex="-1">It does not undo itself <a class="header-anchor" href="#it-does-not-undo-itself" aria-label="Permalink to “It does not undo itself”">​</a></h2><p>A rewrite stays in your files. If a name was renamed that should not have been (for example a function a package declares and PHP also provides), fixing the setting and running <code>prefix</code> again will not put the original name back, because the file no longer contains it. Use <code>git checkout</code> on those files, then fix the setting, then run <code>prefix</code> again.</p><p>Additionally, changing any of the prefixes in your config will <em>not</em> update those prefixes in your project files. You will have to do a search and replace for this.</p><h2 id="names-built-at-run-time" tabindex="-1">Names built at run time <a class="header-anchor" href="#names-built-at-run-time" aria-label="Permalink to “Names built at run time”">​</a></h2><p>Strauss-RS renames names it can read in the code: <code>use</code> lines, type hints, <code>new Foo</code>, <code>Foo::bar()</code>, docblocks, and class names that appear whole inside strings. A name that is put together while the code runs, such as <code>&#39;Acme\\\\&#39; . $name</code>, is not found and is not changed. If your code does that, write the prefixed namespace into the string by hand.</p><p>Where a string that is joined to something else with <code>.</code>, or has a variable inside it, ends in the start of a renamed namespace (<code>&#39;Acme\\\\&#39; . $name</code> when <code>Acme\\Core</code> is renamed), <code>prefix</code> warns with the file and line. A name built in other ways, such as <code>$vendor . &#39;\\\\Core\\\\Client&#39;</code>, is not reported.</p>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};